const now = new Date();
const istOffset = 5.5 * 60 * 60 * 1000;
const istTime = new Date(now.getTime() + istOffset);

return [{
  json: {
    currentDateTime: istTime.toISOString().slice(0, 16).replace('T', ' '),
  },
}];

const aiAgentOutput = $("AI Agent").all()[0]?.json?.output || '';

let cleanedOutput = aiAgentOutput;

// Convert plain URLs to clickable links
cleanedOutput = cleanedOutput.replace(
  /(?<!href=["'])(https?:\/\/[^\s<>"]+)/g,
  '<a href="$1" target="_blank" rel="noopener noreferrer">$1</a>'
);

return { output: cleanedOutput, parseMode: 'HTML' };
